export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [value, setValue] = React.useState<number | undefined>(0);
    return <NumericInput value={value} onChange={(val) => setValue(val)} />;
  },
};
